from collections import Counter
def analyze_grid(I,O=None):
    Sh=shapes(I); H,W=len(I),len(I[0])
    bg=Counter(v for r in I for v in r).most_common(1)[0][0]
    comps={c:ss for c,ss in Sh.items() if c!=bg}
    tgt=[c for c,ss in comps.items() if len(ss)==1]
    items=[(c,cc) for c,ss in comps.items() for cc in ss]
    d=defaultdict(list)
    for c,cc in items: d[norm(cc)].append((c,cc))
    print('bg',bg,'single-shape colors(L):',tgt)
    for c,cc in items:
        ch=O and any(I[y][x]!=O[y][x] for y,x in cc)
        if ch: print('  CHANGED shape: color',c,'cells',cc[:3],'...',len(cc))
    # twin pairs of exactly 2
    def dL(cc):
        lc=comps[tgt[0]][0]
        return min(max(abs(y1-y2),abs(x1-x2)) for y1,x1 in cc for y2,x2 in lc)
    cands=[]
    for pat,lst in d.items():
        if len(lst)==2:
            ds=sorted((dL(cc),c) for c,cc in lst)
            cands.append((ds[0][0],pat,ds))
            print('  twin pair pat',pat[:4],'dists to L:',ds)
    cands.sort()
    print('  SELECTED pair (nearest nearer-member):',cands[0][1][:4],'-> recolor member with dL',cands[0][2][1][0],'color',cands[0][2][1][1],'to',tgt[0])
    return tgt[0]
